//! `vectors.json` was generated by running ent-wallet's own `getVaultInternals`,
//! `getVaultMipsMemoListBytes`, `getP2SingletonMessagePuzzleHash` and
//! `getP2ConditionsOrSingletonPuzzleHashFromFixedConditionsHash` with the keys from its
//! `test/fixtures/vaultKeys.ts`. The Legacy custody vectors and the Legacy recovery vector match the
//! snapshots pinned in its `vault.spec.ts`.

use chia_wallet_sdk::{
    clvmr::serde::node_to_bytes,
    driver::{P2ConditionsOrSingleton, vault_recovery_delegated_puzzle_hash},
    test::{BlsPair, K1Pair, R1Pair},
    types::puzzles::AddDelegatedPuzzleWrapper,
};
use serde::Deserialize;

use super::*;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Vectors {
    launcher_id: String,
    vaults: Vec<VaultVector>,
    p2_singletons: Vec<P2SingletonVector>,
    p2_conditions_or_singleton: P2ConditionsOrSingletonVector,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct VaultVector {
    name: String,
    version: String,
    state: String,
    amount: Option<String>,
    inner_puzzle_hash: String,
    memo: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct P2SingletonVector {
    nonce: usize,
    puzzle_hash: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct P2ConditionsOrSingletonVector {
    nonce: usize,
    fixed_conditions_hash: String,
    puzzle_hash: String,
}

fn vectors() -> Vectors {
    serde_json::from_str(include_str!("vectors.json")).expect("invalid vectors")
}

fn bytes32(hex: &str) -> Bytes32 {
    Bytes32::new(hex::decode(hex).unwrap().try_into().unwrap())
}

fn r1(hex: &str) -> R1PublicKey {
    R1PublicKey::from_bytes(&hex::decode(hex).unwrap().try_into().unwrap()).unwrap()
}

fn k1(hex: &str) -> K1PublicKey {
    K1PublicKey::from_bytes(&hex::decode(hex).unwrap().try_into().unwrap()).unwrap()
}

fn bls(hex: &str) -> PublicKey {
    PublicKey::from_bytes(&hex::decode(hex).unwrap().try_into().unwrap()).unwrap()
}

