fn launcher(byte: u8) -> VaultMember {
    VaultMember::singleton(Bytes32::new([byte; 32]))
}

/// The configs from ent-wallet's `test/fixtures/vaultKeys.ts`, and a secp256k1 config.
fn fixture(name: &str, version: VaultVersion) -> VaultConfig {
    let (custody, recovery, recovery_timelock) = match name {
        "oneOfOne" => (
            VaultSigners::new(vec![r1_a()], 1),
            VaultSigners::new(vec![bls_key()], 1),
            3600,
        ),
        "mixedMofN" => (
            VaultSigners::new(vec![r1_a(), passkey(), launcher(0x21)], 2),
            VaultSigners::new(vec![bls_key(), r1_b(), launcher(0x22)], 2),
            7200,
        ),
        "nestedVaults" => (
            VaultSigners::new(vec![launcher(0x31), launcher(0x32)], 1),
            VaultSigners::new(vec![launcher(0x33)], 1),
            10_800,
        ),
        "custodyWithPasskey" => (
            VaultSigners::new(vec![passkey()], 1),
            VaultSigners::new(vec![bls_key()], 1),
            86_400,
        ),
        "k1Custody" => (
            VaultSigners::new(vec![k1_key(), r1_a()], 1),
            VaultSigners::new(vec![k1_key()], 1),
            60,
        ),
        _ => panic!("unknown fixture {name}"),
    };

    VaultConfig {
        custody,
        recovery,
        recovery_timelock,
        version,
    }
}

fn version(name: &str) -> VaultVersion {
    match name {
        "LEGACY" => VaultVersion::Legacy,
        "FORCE_SINGLETON_RECREATION" => VaultVersion::ForceSingletonRecreation,
        _ => panic!("unknown version {name}"),
    }
}

/// Decoded members are in the order of the memo, which is sorted by member hash.
fn normalize_signers(signers: &VaultSigners) -> VaultSigners {
    let mut members = signers.members.clone();
    members.sort_by_key(|&member| mips_puzzle_hash(0, vec![], member_puzzle_hash(member), false));
    VaultSigners::new(members, signers.threshold)
}

fn normalize(config: &VaultConfig) -> VaultConfig {
    VaultConfig {
        custody: normalize_signers(&config.custody),
        recovery: normalize_signers(&config.recovery),
        ..config.clone()
    }
}

#[test]
fn test_ent_wallet_vectors() -> anyhow::Result<()> {
    let vectors = vectors();
    assert_eq!(vectors.vaults.len(), 12);

    for vector in vectors.vaults {
        let mut allocator = Allocator::new();
        let version = version(&vector.version);
        let custody_hash = bytes32(&vector.inner_puzzle_hash);

        let (built, decoded_expected) = match vector.state.as_str() {
            "custody" => {
                let config = fixture(&vector.name, version);
                assert_eq!(vault_hashes(&config)?.custody_hash, custody_hash.into());
                (
                    build_vault(&mut allocator, &config)?,
                    DecodedVault::Custody(normalize(&config)),
                )
            }
            "recovery" => {
                // oneOfOne, recovering to mixedMofN.
                let current = fixture("oneOfOne", version);
                let post_recovery = fixture("mixedMofN", version);
                let config = VaultRecoveryConfig {
                    custody: current.custody,
                    recovery_timelock: current.recovery_timelock,
                    version,
                    recovery_custody_hash: vault_hashes(&post_recovery)?.custody_hash.into(),
                    amount: vector.amount.as_deref().unwrap().parse()?,
                };
                (
                    build_vault_recovery(&mut allocator, &config, &post_recovery)?,
                    DecodedVault::Recovery {
                        config: config.clone(),
                        post_recovery: normalize(&post_recovery),
                    },
                )
            }
            state => panic!("unknown state {state}"),
        };

        let name = format!("{} {} {}", vector.name, vector.version, vector.state);

        assert_eq!(built.hashes.custody_hash, custody_hash.into(), "{name}");
        assert_eq!(
            hex::encode(node_to_bytes(&allocator, built.memo_list)?),
            vector.memo,
            "{name}"
        );

        let decoded = decode_vault_memo_list_bytes(
            &mut allocator,
            &hex::decode(&vector.memo)?,
            custody_hash,
        )?;
        assert_eq!(decoded, decoded_expected, "{name}");
    }

    Ok(())
}

#[test]
fn test_ent_wallet_p2_vectors() {
    let vectors = vectors();
    let launcher_id = bytes32(&vectors.launcher_id);

    for vector in vectors.p2_singletons {
        assert_eq!(
            p2_singleton_puzzle_hash(launcher_id, vector.nonce),
            bytes32(&vector.puzzle_hash)
        );
    }

    let vector = vectors.p2_conditions_or_singleton;
    let p2 = P2ConditionsOrSingleton::new(
        launcher_id,
        vector.nonce,
        bytes32(&vector.fixed_conditions_hash),
    );
    assert_eq!(p2.tree_hash(), bytes32(&vector.puzzle_hash).into());
}

#[test]
fn test_member_order_is_canonical() -> anyhow::Result<()> {
    let config = fixture("mixedMofN", VaultVersion::Legacy);
    let mut reversed = config.clone();
    reversed.custody.members.reverse();
    reversed.recovery.members.reverse();

    let mut allocator = Allocator::new();
    let built = build_vault(&mut allocator, &config)?;
    let reversed = build_vault(&mut allocator, &reversed)?;

    assert_eq!(built.hashes, reversed.hashes);
    assert_eq!(
        node_to_bytes(&allocator, built.memo_list)?,
        node_to_bytes(&allocator, reversed.memo_list)?
    );

    Ok(())
}

/// The recovery restrictions must wrap delegated puzzles the same way as the SDK's clear signing,
/// which recovery keys rely on to know what they're signing.
#[test]
fn test_recovery_restrictions_match_clear_signing() {
    let delegated_puzzle_hash = Bytes32::new([7; 32]);
    let custody_member_hash = TreeHash::new([8; 32]);

    for version in [VaultVersion::Legacy, VaultVersion::ForceSingletonRecreation] {
        let mut wrapped = TreeHash::from(delegated_puzzle_hash);

        for restriction in recovery_restrictions(custody_member_hash, 100, version)
            .into_iter()
            .rev()
        {
            wrapped =
                AddDelegatedPuzzleWrapper::new(restriction.puzzle_hash, wrapped).curry_tree_hash();
        }

        assert_eq!(
            Bytes32::from(wrapped),
            vault_recovery_delegated_puzzle_hash(
                delegated_puzzle_hash,
                custody_member_hash.into(),
                100,
                version,
            )
        );
    }
}

fn sdk_custody(case: &str) -> VaultSigners {
    match case {
        "single_k1" => VaultSigners::new(vec![VaultMember::secp256k1(K1Pair::new(1).pk)], 1),
        "single_bls" => VaultSigners::new(vec![VaultMember::bls(BlsPair::new(1).pk)], 1),
        "two_of_four_mixed" => VaultSigners::new(
            vec![
                VaultMember::secp256k1(K1Pair::new(1).pk),
                VaultMember::secp256r1(R1Pair::new(2).pk),
                VaultMember::passkey(R1Pair::new(3).pk),
                VaultMember::bls(BlsPair::new(4).pk),
            ],
            2,
        ),
        "nested_vault" => VaultSigners::new(
            vec![
                VaultMember::passkey(R1Pair::new(1).pk),
                VaultMember::singleton(Bytes32::new([42; 32])),
            ],
            1,
        ),
        _ => unreachable!(),
    }
}

fn sdk_recovery(case: &str) -> VaultSigners {
    match case {
        "single_k1" => VaultSigners::new(vec![VaultMember::secp256k1(K1Pair::new(100).pk)], 1),
        "single_vault" => {
            VaultSigners::new(vec![VaultMember::singleton(Bytes32::new([43; 32]))], 1)
        }
        "two_of_two" => VaultSigners::new(
            vec![
                VaultMember::secp256r1(R1Pair::new(101).pk),
                VaultMember::singleton(Bytes32::new([44; 32])),
            ],
            2,
        ),
        _ => unreachable!(),
    }
}

/// The same matrix as `test_vault_memo_roundtrip` in the SDK's `vault_tests.rs`, checking that
/// config -> memo -> config round trips in both states and versions.
#[test]
fn test_round_trip_matrix() -> anyhow::Result<()> {
    for custody in [
        "single_k1",
        "single_bls",
        "two_of_four_mixed",
        "nested_vault",
    ] {
        for recovery in ["single_k1", "single_vault", "two_of_two"] {
            for version in [VaultVersion::Legacy, VaultVersion::ForceSingletonRecreation] {
                let mut allocator = Allocator::new();

                let config = VaultConfig {
                    custody: sdk_custody(custody),
                    recovery: sdk_recovery(recovery),
                    recovery_timelock: 86_400,
                    version,
                };

                let built = build_vault(&mut allocator, &config)?;
                let bytes = node_to_bytes(&allocator, built.memo_list)?;
                let custody_hash = built.hashes.custody_hash.into();

                let decoded = decode_vault_memo_list_bytes(&mut allocator, &bytes, custody_hash)?;
                assert_eq!(decoded, DecodedVault::Custody(normalize(&config)));

                // Rebuilding the decoded config reproduces the memo byte for byte.
                let DecodedVault::Custody(decoded) = decoded else {
                    unreachable!();
                };
                let rebuilt = build_vault(&mut allocator, &decoded)?;
                assert_eq!(node_to_bytes(&allocator, rebuilt.memo_list)?, bytes);

                // Recovery to the swapped config.
                let post_recovery = VaultConfig {
                    custody: sdk_recovery(recovery),
                    recovery: sdk_custody(custody),
                    ..config.clone()
                };
                let recovery_config = VaultRecoveryConfig {
                    custody: config.custody.clone(),
                    recovery_timelock: config.recovery_timelock,
                    version,
                    recovery_custody_hash: vault_hashes(&post_recovery)?.custody_hash.into(),
                    amount: 1,
                };

                let built = build_vault_recovery(&mut allocator, &recovery_config, &post_recovery)?;
                assert!(built.recovery_finish_puzzle.is_some());

                let bytes = node_to_bytes(&allocator, built.memo_list)?;
                let decoded = decode_vault_memo_list_bytes(
                    &mut allocator,
                    &bytes,
                    built.hashes.custody_hash.into(),
                )?;

                let DecodedVault::Recovery {
                    config: decoded_config,
                    post_recovery: decoded_post_recovery,
                } = decoded
                else {
                    panic!("expected the recovery state");
                };

                assert_eq!(
                    decoded_config,
                    VaultRecoveryConfig {
                        custody: normalize_signers(&recovery_config.custody),
                        ..recovery_config.clone()
                    }
                );
                assert_eq!(decoded_post_recovery, normalize(&post_recovery));

                let rebuilt =
                    build_vault_recovery(&mut allocator, &decoded_config, &decoded_post_recovery)?;
                assert_eq!(node_to_bytes(&allocator, rebuilt.memo_list)?, bytes);
            }
        }
    }

    Ok(())
}

fn memo_bytes(config: &VaultConfig) -> anyhow::Result<(Vec<u8>, Bytes32)> {
    let mut allocator = Allocator::new();
    let built = build_vault(&mut allocator, config)?;
    Ok((
        node_to_bytes(&allocator, built.memo_list)?,
        built.hashes.custody_hash.into(),
    ))
}

#[test]
fn test_rejects_hash_mismatch() -> anyhow::Result<()> {
    let (bytes, _) = memo_bytes(&fixture("mixedMofN", VaultVersion::Legacy))?;
    let (_, other_custody_hash) = memo_bytes(&fixture("oneOfOne", VaultVersion::Legacy))?;

    let mut allocator = Allocator::new();
    assert!(matches!(
        decode_vault_memo_list_bytes(&mut allocator, &bytes, other_custody_hash),
        Err(VaultLayoutError::HashMismatch)
    ));

    // The version is committed to by the custody hash too.
    let (_, force_singleton_recreation) = memo_bytes(&fixture(
        "mixedMofN",
        VaultVersion::ForceSingletonRecreation,
    ))?;
    assert!(matches!(
        decode_vault_memo_list_bytes(&mut allocator, &bytes, force_singleton_recreation),
        Err(VaultLayoutError::HashMismatch)
    ));

    Ok(())
}

#[test]
fn test_rejects_tampered_memos() -> anyhow::Result<()> {
    let (bytes, custody_hash) = memo_bytes(&fixture("oneOfOne", VaultVersion::Legacy))?;
    let hex = hex::encode(&bytes);

    // Each member, restriction and wrapper declares its own puzzle hash, so the memo still hashes
    // to the custody hash after changing what it reveals. Those memos must not decode.
    let tampered = [
        // A different custody key, whose member puzzle hash is left as is.
        (hex.replace(
            "036caa4b6d2d53dc40179e97eeaeb837086d3c22d9aaf0ad73588629c411fc425b",
            "0341d9d28026325677be1fdaafb0bca8108181e412db9d694ff39e85f0a82664da",
        ), false),
        // A different BLS recovery key, whose member puzzle hash is left as is.
        (hex.replace(
            "91c6ab26e047e4235d1cce5d09b536da5501297e9ccbc146a794612e6a3bb880cc4d3ad79a7760ae35b34324cc255dc4",
            "97f1d3a73197d7942695638c4fa9ac0fc3688c4f9774b905a14e3a3f171bac586c55e83ff97a1aeffb3af00adb22c6bb",
        ), false),
        // A different recovery timelock, whose restriction puzzle hash is left as is.
        (hex.replace("ff820e1080", "ff820e1180"), false),
        // A different nonce for the top level, which changes the hash.
        (hex.replacen("ffff80ff80ff01", "ffff01ff80ff01", 1), true),
    ];

    for (tampered, changes_hash) in tampered {
        assert_ne!(tampered, hex);

        let mut allocator = Allocator::new();
        let result =
            decode_vault_memo_list_bytes(&mut allocator, &hex::decode(&tampered)?, custody_hash);

        if changes_hash {
            assert!(
                matches!(result, Err(VaultLayoutError::HashMismatch)),
                "{result:?}"
            );
        } else {
            assert!(
                matches!(result, Err(VaultLayoutError::UnsupportedMemo)),
                "{result:?}"
            );
        }
    }

    Ok(())
}

#[test]
fn test_rejects_malformed_memos() -> anyhow::Result<()> {
    let mut allocator = Allocator::new();
    let custody_hash = Bytes32::new([1; 32]);

    // An empty memo list, a hint only, and something that isn't a CHIP-0043 memo.
    let nil = NodePtr::NIL;
    let hint = vec![Bytes32::new([0x99; 32])].to_clvm(&mut allocator)?;
    let garbage = vec![("CHIP-0043".to_string(), (1, (2, 3)))].to_clvm(&mut allocator)?;

    for memo_list in [nil, hint, garbage] {
        assert!(decode_vault_memo_list(&mut allocator, memo_list, custody_hash).is_err());
    }

    Ok(())
}

#[test]
fn test_rejects_oversized_memos() -> anyhow::Result<()> {
    let mut allocator = Allocator::new();

    let bytes = vec![0x80; MAX_VAULT_MEMO_LIST_SIZE + 1];
    assert!(matches!(
        decode_vault_memo_list_bytes(&mut allocator, &bytes, Bytes32::default()),
        Err(VaultLayoutError::MemoTooLarge)
    ));

    // A memo which is nested too deeply to decode.
    let mut inner_puzzle = InnerPuzzleMemo::new(
        0,
        vec![],
        MemoKind::Member(MemberMemo::new(Bytes32::default(), NodePtr::NIL)),
    );

    for _ in 0..100 {
        inner_puzzle = InnerPuzzleMemo::new(
            0,
            vec![],
            MemoKind::MofN(MofNMemo::new(1, vec![inner_puzzle])),
        );
    }

    let memo = MipsMemo::new(inner_puzzle);
    let custody_hash = memo.inner_puzzle_hash().into();
    let memo_list = vec![memo].to_clvm(&mut allocator)?;

    assert!(matches!(
        decode_vault_memo_list(&mut allocator, memo_list, custody_hash),
        Err(VaultLayoutError::Driver(DriverError::MipsMemoTooDeep))
    ));

    Ok(())
}

/// Only one level of recovery can be revealed, since the vault is recreated in its normal state.
#[test]
fn test_rejects_nested_recovery() -> anyhow::Result<()> {
    let mut allocator = Allocator::new();

    let post_recovery = fixture("mixedMofN", VaultVersion::Legacy);
    let config = VaultRecoveryConfig {
        custody: fixture("oneOfOne", VaultVersion::Legacy).custody,
        recovery_timelock: 3600,
        version: VaultVersion::Legacy,
        recovery_custody_hash: vault_hashes(&post_recovery)?.custody_hash.into(),
        amount: 1,
    };
    let inner = build_vault_recovery(&mut allocator, &config, &post_recovery)?;

    // Wrap the recovery state memo in another recovery finish member by hand.
    let outer = VaultRecoveryConfig {
        recovery_custody_hash: inner.hashes.custody_hash.into(),
        ..config.clone()
    };
    let finish_puzzle = recovery_finish_puzzle(&mut allocator, &outer, inner.memo_list)?;
    let finish_puzzle_hash = tree_hash(&allocator, finish_puzzle);
    let custody = signers_memo(&mut allocator, &outer.custody, vec![])?;
    let timelock = RestrictionMemo::timelock(&mut allocator, 3600, true)?;
    let recovery = InnerPuzzleMemo::new(
        0,
        vec![timelock],
        MemoKind::Member(MemberMemo::new(finish_puzzle_hash.into(), finish_puzzle)),
    );
    let memo = MipsMemo::new(InnerPuzzleMemo::new(
        0,
        vec![],
        MemoKind::MofN(MofNMemo::new(1, vec![custody, recovery])),
    ));
    let custody_hash = memo.inner_puzzle_hash().into();
    let memo_list = vec![memo].to_clvm(&mut allocator)?;

    assert!(matches!(
        decode_vault_memo_list(&mut allocator, memo_list, custody_hash),
        Err(VaultLayoutError::UnsupportedMemo)
    ));

    Ok(())
}

#[test]
fn test_rejects_invalid_configs() {
    let mut config = fixture("mixedMofN", VaultVersion::Legacy);

    config.custody.threshold = 4;
    assert!(matches!(
        vault_hashes(&config),
        Err(VaultLayoutError::InvalidSigners)
    ));

    config.custody.threshold = 0;
    assert!(matches!(
        vault_hashes(&config),
        Err(VaultLayoutError::InvalidSigners)
    ));

    config.custody = VaultSigners::new(vec![], 1);
    assert!(matches!(
        vault_hashes(&config),
        Err(VaultLayoutError::InvalidSigners)
    ));

    config.custody = VaultSigners::new(vec![r1_a()], 2);
    assert!(matches!(
        vault_hashes(&config),
        Err(VaultLayoutError::InvalidSigners)
    ));

    config.custody = VaultSigners::new(
        vec![VaultMember::Custom {
            puzzle_hash: Bytes32::default(),
        }],
        1,
    );
    assert!(matches!(
        vault_hashes(&config),
        Err(VaultLayoutError::CustomMember)
    ));

    // A recovery whose post-recovery config doesn't match the recovery custody hash.
    let post_recovery = fixture("oneOfOne", VaultVersion::Legacy);
    let recovery = VaultRecoveryConfig {
        custody: post_recovery.custody.clone(),
        recovery_timelock: 3600,
        version: VaultVersion::Legacy,
        recovery_custody_hash: Bytes32::default(),
        amount: 1,
    };
    assert!(matches!(
        build_vault_recovery(&mut Allocator::new(), &recovery, &post_recovery),
        Err(VaultLayoutError::RecoveryCustodyHashMismatch)
    ));
}
